/**
 * Every query filters by `orgId` and by `archived_at`.
 *
 * Owner C implements `@/server/repositories/issue-repository`. Seed with
 * `seedTwoTenants()` from `tests/helpers/db.ts` so the negative case is a real
 * row in the other tenant.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as permissions from "@/lib/permissions";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let north: Tenant;
let acme: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  north = await createTenant("northwind-issues");
  acme = await createTenant("acme-issues");
});

afterAll(() => {
  cleanup();
});

/** Inserts one issue directly through the repository, bypassing the service. */
async function insertIssue(
  tenant: Tenant,
  overrides: Partial<{ title: string; assigneeId: (typeof tenant.userIds)["member"] | null }> = {},
) {
  const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
  return issueRepo.insertIssue(
    issueInput(tenant.org.id, tenant.project.id, overrides),
    tenant.userIds.owner,
    number,
  );
}

describe("repositories/issue-repository", () => {
  it("excludes another tenant's issues from every list query", async () => {
    const northIssue = await insertIssue(north, { title: "North only" });
    await insertIssue(acme, { title: "Acme only" });

    const page = await issueRepo.listIssues({
      orgId: north.org.id,
      limit: 25,
      cursor: null,
    });

    expect(page.items.map((issue) => issue.id)).toContain(northIssue.id);
    expect(page.items.every((issue) => issue.orgId === north.org.id)).toBe(true);
  });

  it("returns null for an id that belongs to another tenant", async () => {
    const issue = await insertIssue(north, { title: "Northwind private" });

    await expect(issueRepo.findIssueById(acme.org.id, issue.id)).resolves.toBeNull();
    await expect(
      issueRepo.findIssueById(north.org.id, issue.id),
    ).resolves.not.toBeNull();
  });

  it("hides archived issues unless includeArchived is set", async () => {
    const issue = await insertIssue(north, { title: "To be archived" });
    await issueRepo.archiveIssue(north.org.id, issue.id);

    const page = await issueRepo.listIssues({
      orgId: north.org.id,
      limit: 100,
      cursor: null,
    });

    expect(page.items.map((row) => row.id)).not.toContain(issue.id);
  });

  it("returns archived issues when the scope asks for them", async () => {
    const issue = await insertIssue(north, { title: "Also archived" });
    await issueRepo.archiveIssue(north.org.id, issue.id);

    const page = await issueRepo.listIssues({
      orgId: north.org.id,
      limit: 100,
      cursor: null,
      includeArchived: true,
    });

    expect(page.items.map((row) => row.id)).toContain(issue.id);
  });

  it("applies status, priority, assignee and label filters together", async () => {
    const label = await labelRepo.insertLabel({
      orgId: north.org.id,
      name: "urgent-bug",
      color: "#ef4444",
      description: null,
    });

    const number = await issueRepo.nextIssueNumber(north.org.id, north.project.id);
    const matching = await issueRepo.insertIssue(
      {
        ...issueInput(north.org.id, north.project.id, {
          title: "Matches every filter",
          assigneeId: north.userIds.member,
        }),
        status: "in_progress",
        priority: "urgent",
        labelIds: [label.id],
      },
      north.userIds.owner,
      number,
    );

    // A near-identical issue that only differs by status must not match.
    const otherNumber = await issueRepo.nextIssueNumber(north.org.id, north.project.id);
    await issueRepo.insertIssue(
      {
        ...issueInput(north.org.id, north.project.id, {
          title: "Wrong status",
          assigneeId: north.userIds.member,
        }),
        status: "backlog",
        priority: "urgent",
        labelIds: [label.id],
      },
      north.userIds.owner,
      otherNumber,
    );

    const page = await issueRepo.listIssues({
      orgId: north.org.id,
      limit: 100,
      cursor: null,
      status: ["in_progress"],
      priority: ["urgent"],
      assigneeId: north.userIds.member,
      labelIds: [label.id],
    });

    expect(page.items.map((row) => row.id)).toEqual([matching.id]);
  });

  it("pages with a cursor and reports the total", async () => {
    const org = await createTenant("pager-issues");
    for (const title of ["First", "Second", "Third"]) {
      const number = await issueRepo.nextIssueNumber(org.org.id, org.project.id);
      await issueRepo.insertIssue(
        issueInput(org.org.id, org.project.id, { title }),
        org.userIds.owner,
        number,
      );
    }

    const firstPage = await issueRepo.listIssues({
      orgId: org.org.id,
      limit: 2,
      cursor: null,
    });

    expect(firstPage.items).toHaveLength(2);
    expect(firstPage.total).toBe(3);
    expect(firstPage.nextCursor).not.toBeNull();

    const secondPage = await issueRepo.listIssues({
      orgId: org.org.id,
      limit: 2,
      cursor: firstPage.nextCursor,
    });

    expect(secondPage.items).toHaveLength(1);
    expect(secondPage.nextCursor).toBeNull();

    const seenIds = new Set([
      ...firstPage.items.map((row) => row.id),
      ...secondPage.items.map((row) => row.id),
    ]);
    expect(seenIds.size).toBe(3);
  });

  it("performs no authorization of its own", async () => {
    const canSpy = vi.spyOn(permissions, "can");
    const assertCanSpy = vi.spyOn(permissions, "assertCan");

    const issue = await insertIssue(north, { title: "No auth check here" });
    await issueRepo.findIssueById(north.org.id, issue.id);
    await issueRepo.listIssues({ orgId: north.org.id, limit: 10, cursor: null });

    expect(canSpy).not.toHaveBeenCalled();
    expect(assertCanSpy).not.toHaveBeenCalled();

    canSpy.mockRestore();
    assertCanSpy.mockRestore();
  });
});

/**
 * Project rows: cursor listing, slug/key uniqueness, soft delete and restore.
 *
 * Must call (do not reimplement): archivePatch, restorePatch, shouldFilterArchived, uniqueSlug
 */
import { and, count, desc, eq, inArray, isNotNull, like, lt, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import {
  archivePatch,
  restorePatch,
  shouldFilterArchived,
} from "@/lib/soft-delete";
import { getDb, issues, projects } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toProject } from "./_mappers";
import type {
  CreateProjectInput,
  ListProjectsInput,
  UpdateProjectInput,
} from "@/schemas/project";
import type { ArchiveScope, OrgId, Page, ProjectId } from "@/types/common";
import type { Project, ProjectStats } from "@/types/project";

export async function findProjectById(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project | null> {
  const row = getDb()
    .select()
    .from(projects)
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .get();
  return row ? toProject(row) : null;
}

export async function findProjectBySlug(
  orgId: OrgId,
  slug: string,
): Promise<Project | null> {
  const row = getDb()
    .select()
    .from(projects)
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.slug, slug)))
    .get();
  return row ? toProject(row) : null;
}

export async function listProjects(
  input: ListProjectsInput,
): Promise<Page<Project>> {
  const db = getDb();
  const sort = { sortColumn: projects.createdAt, idColumn: projects.id };

  // The rows and the total must agree on the archive scope, so normalise the
  // filter's loose `includeArchived` into one `ArchiveScope` up front.
  const scope: ArchiveScope = shouldFilterArchived(input)
    ? {}
    : { includeArchived: true };

  const filters = compact(
    orgPredicate(projects.orgId, input.orgId),
    livePredicate(projects.archivedAt, scope),
    input.status === undefined ? undefined : eq(projects.status, input.status),
    input.query === undefined
      ? undefined
      : like(projects.name, `%${input.query}%`),
  );

  const total = db
    .select({ value: count() })
    .from(projects)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(projects)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(projects.createdAt), desc(projects.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(rows, input.limit, total?.value ?? 0, toProject, (row) => ({
    id: row.id,
    sortValue: row.createdAt,
  }));
}

/** Counts live projects by default; the `projects` quota reads this. */
export async function countProjects(
  orgId: OrgId,
  scope: ArchiveScope = {},
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(projects)
    .where(
      and(
        ...compact(
          orgPredicate(projects.orgId, orgId),
          livePredicate(projects.archivedAt, scope),
        ),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertProject(
  input: CreateProjectInput,
): Promise<Project> {
  const taken = await listTakenProjectSlugs(input.orgId);
  const slug = uniqueSlug(input.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(projects)
    .values({
      id: newId(),
      orgId: input.orgId,
      name: input.name,
      slug,
      key: input.key,
      description: input.description,
      visibility: input.visibility,
      status: "active",
      leadId: input.leadId,
      color: input.color,
      startsAt: null,
      targetDate: input.targetDate,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toProject(row);
}

export async function updateProject(
  input: UpdateProjectInput,
): Promise<Project> {
  const row = getDb()
    .update(projects)
    .set({
      ...(input.name === undefined ? {} : { name: input.name }),
      ...(input.description === undefined
        ? {}
        : { description: input.description }),
      ...(input.visibility === undefined
        ? {}
        : { visibility: input.visibility }),
      ...(input.status === undefined ? {} : { status: input.status }),
      ...(input.leadId === undefined ? {} : { leadId: input.leadId }),
      ...(input.color === undefined ? {} : { color: input.color }),
      ...(input.targetDate === undefined
        ? {}
        : { targetDate: input.targetDate }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(projects.orgId, input.orgId),
        eq(projects.id, input.projectId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Project ${input.projectId} not found`);
  return toProject(row);
}

export async function archiveProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const row = getDb()
    .update(projects)
    .set(archivePatch())
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .returning()
    .get();

  if (!row) throw new Error(`Project ${projectId} not found`);
  return toProject(row);
}

export async function restoreProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const row = getDb()
    .update(projects)
    .set(restorePatch())
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .returning()
    .get();

  if (!row) throw new Error(`Project ${projectId} not found`);
  return toProject(row);
}

/** Includes archived slugs — a restored project must not collide. */
export async function listTakenProjectSlugs(
  orgId: OrgId,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: projects.slug })
    .from(projects)
    .where(orgPredicate(projects.orgId, orgId))
    .all();
  return rows.map((row) => row.slug);
}

/** Open/closed/overdue counters plus the last write, for the project card. */
export async function getProjectStats(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<ProjectStats> {
  const db = getDb();
  const scope = and(
    orgPredicate(issues.orgId, orgId),
    eq(issues.projectId, projectId),
    ...compact(livePredicate(issues.archivedAt, {})),
  );

  const closed = db
    .select({ value: count() })
    .from(issues)
    .where(and(scope, inArray(issues.status, [...CLOSED_ISSUE_STATUSES])))
    .get();

  const all = db.select({ value: count() }).from(issues).where(scope).get();

  const overdue = db
    .select({ value: count() })
    .from(issues)
    .where(
      and(
        scope,
        isNotNull(issues.dueAt),
        lt(issues.dueAt, toIsoTimestamp(new Date())),
      ),
    )
    .get();

  const lastActivity = db
    .select({ value: sql<string | null>`max(${issues.updatedAt})` })
    .from(issues)
    .where(scope)
    .get();

  const closedCount = closed?.value ?? 0;

  return {
    projectId,
    openIssues: (all?.value ?? 0) - closedCount,
    closedIssues: closedCount,
    overdueIssues: overdue?.value ?? 0,
    lastActivityAt:
      lastActivity?.value == null ? null : toIsoTimestamp(lastActivity.value),
  };
}

