/**
 * Next per-project issue number. Reads the project's own high-water mark
 * rather than `MAX(issues.number)`: an issue that is archived, or moved away
 * to another project, keeps its number retired, which a derive-from-rows
 * query could not express once the row no longer lives in this project.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: projects.lastIssueNumber })
    .from(projects)
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .get();
  return (row?.value ?? 0) + 1;
}

/** Records that `number` is now the highest ever issued for the project. */
async function claimIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
  number: number,
): Promise<void> {
  getDb()
    .update(projects)
    .set({ lastIssueNumber: number })
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .run();
}

