/**
 * Moves an issue to another project of the same workspace (ADR 0011). Gated
 * on both halves of the operation: `issue:update` on the issue being moved,
 * the same permission any edit needs, and `issue:create` on the destination,
 * the same permission creating an issue there needs. The destination's
 * per-project quota applies exactly as it would to a new issue.
 *
 * The issue is renumbered into the target project's sequence; its old number
 * is retired — `issueRepo.nextIssueNumber` never reissues it, even if the
 * issue is later moved away and back. A move within the same project is a
 * no-op: nothing changes and no event is published.
 */
export async function moveIssueToProject(
  actor: Actor,
  input: MoveIssueToProjectInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  if (before.projectId === input.toProjectId) return before;

  const toProject = requireFound(
    await projectRepo.findProjectById(input.orgId, input.toProjectId),
    "Project",
    input.toProjectId,
  );
  assertNotArchived("Project", toProject.id, toProject);
  assertCan(actor, "issue:create", projectResource(toProject));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, toProject.id);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${toProject.key}`,
    );
  }

  const fromProjectId = before.projectId;
  const fromNumber = before.number;
  const toNumber = await issueRepo.nextIssueNumber(input.orgId, toProject.id);

  const after = await issueRepo.moveIssueToProject(
    input.orgId,
    input.issueId,
    toProject.id,
    toNumber,
  );

  await emit("issue.moved", {
    ...actorEnvelope(actor),
    issueId: after.id,
    fromProjectId,
    toProjectId: toProject.id,
    fromNumber,
    toNumber,
  });

  return after;
}

